<template>
  <view class="page">
    <view class="nav"><button class="back" @tap="goBack">‹</button><view><text class="title">睡眠记录</text><text class="date">{{ dateLabel }}</text></view><view class="nav-space" /></view>
    <view class="hero"><image src="/static/illustrations/xuxu-sleep-reminder.png" mode="aspectFill" /><view class="hero-copy"><text>和序序一起，好好睡一觉</text><text>记录作息，也记录梦里的小片段</text></view></view>
    <view class="section"><text class="section-title">昨晚睡了多久？</text><text class="section-sub">选择入睡和起床时间，时长会自动计算</text>
      <view class="time-pair"><picker mode="time" :value="bedtime" @change="setBedtime"><view class="time-cell"><text>入睡时间</text><strong>{{ bedtime }}</strong><text>›</text></view></picker><view class="dash">—</view><picker mode="time" :value="wakeTime" @change="setWakeTime"><view class="time-cell"><text>起床时间</text><strong>{{ wakeTime }}</strong><text>›</text></view></picker></view>
      <view class="duration"><text>预计睡眠时长</text><strong>{{ formatSleepDuration(sleepMinutes) }}</strong></view>
    </view>
    <view class="section"><text class="section-title">睡眠质量</text><view class="quality-row"><button v-for="item in qualities" :key="item.value" :class="['quality', { selected: quality === item.value }]" @tap="quality = item.value">{{ item.label }}</button></view></view>
    <view class="section"><view class="section-title-row"><text class="section-title">昨晚做了什么梦？</text><text class="optional">选填</text></view><textarea v-model="dream" class="dream" maxlength="160" placeholder="记下一点画面、情绪，或只写一句话" /></view>
    <button class="save" @tap="save">保存睡眠记录</button>
    <view class="history"><view class="history-head"><text>最近睡眠</text><text>{{ history.length }} 条</text></view><view v-if="history.length" v-for="item in history" :key="item.date" class="history-row"><view><text>{{ item.date }}</text><text>{{ formatSleepDuration(item.sleep?.durationMinutes || 0) }} · {{ qualityLabel(item.sleep?.quality) }}</text></view><text class="dream-preview">{{ item.sleep?.dream || '没有填写梦境' }}</text></view><view v-else class="empty">保存后，这里会出现你的睡眠记录。</view></view>
  </view>
</template>
<script setup lang="ts">
import { computed, ref } from 'vue';
import { onShow } from '@dcloudio/uni-app';
import { formatSleepDuration, listWellnessJournals, loadWellnessJournal, saveSleep, sleepDuration, type SleepQuality } from '../../features/wellness/wellness-journal.js';
const now = new Date(); const today = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 10); const dateLabel = `${now.getMonth() + 1}月${now.getDate()}日`;
const bedtime = ref(loadWellnessJournal().sleep?.bedtime || '23:00'); const wakeTime = ref(loadWellnessJournal().sleep?.wakeTime || '07:00'); const quality = ref<SleepQuality>(loadWellnessJournal().sleep?.quality || 'good'); const dream = ref(loadWellnessJournal().sleep?.dream || ''); const history = ref(listWellnessJournals().filter((item) => item.sleep));
const sleepMinutes = computed(() => sleepDuration(bedtime.value, wakeTime.value)); const qualities = [{ value: 'poor', label: '不太好' }, { value: 'fair', label: '一般' }, { value: 'good', label: '挺好' }] as const;
function setBedtime(e: { detail: { value: string } }) { bedtime.value = e.detail.value; } function setWakeTime(e: { detail: { value: string } }) { wakeTime.value = e.detail.value; }
function qualityLabel(value?: SleepQuality) { return value === 'good' ? '挺好' : value === 'fair' ? '一般' : '不太好'; }
function save() { saveSleep({ bedtime: bedtime.value, wakeTime: wakeTime.value, quality: quality.value, dream: dream.value.trim() }, today); history.value = listWellnessJournals().filter((item) => item.sleep); uni.showToast({ title: '睡眠已保存', icon: 'success' }); }
function goBack() { uni.navigateBack(); } onShow(() => { history.value = listWellnessJournals().filter((item) => item.sleep); });
</script>
